/** How much of the list carries a price. Shown before importing. */
export function priceListSummary() {
  let priced = 0;
  let drugs = 0;
  UNTH_PRICE_LIST.forEach((i) => {
    if (i.unitPrice) priced += 1;
    if (i.dispensedByPharmacy) drugs += 1;
  });
  return {
    total: UNTH_PRICE_LIST.length,
    priced,
    unpriced: UNTH_PRICE_LIST.length - priced,
    drugs,
    consumables: UNTH_PRICE_LIST.length - drugs,
  };
}
